/**
 * PF-4: the library entry point (`exports["."]` of cli/package.json). Importing it runs nothing: no command parsing,
 * no exit, no output, no read of HOME or the environment. It drives Nexus only as a separate sidecar process, so an
 * embedder cannot skip the sidecar's start-up checks; `ApplicationCore` is deliberately not exported (docs/EMBEDDING.md).
 *
 * The export list is recorded in docs/protocol/LIB_API_VERSIONS.json; changing it needs a new entry there.
 */
export const NEXUS_LIB_API_VERSION = 1;
export { spawnSidecar, SidecarClient, SidecarClientError } from "./sidecar_client.js";
export type {
  ApprovalDecision,
  ApprovalHandler,
  ApprovalRequest,
  PromptOptions,
  SidecarChild,
  SidecarClientErrorCode,
  SidecarExit,
  SpawnSidecarOptions,
} from "./sidecar_client.js";
export type { ErrorCode, SidecarCommand, SidecarEvent } from "./protocol.js";
export type { EngineeringOutcome, ExecutionState, TurnResult } from "./core/turn.js";
  1 │ /**
  2 │  * PF-4: a client for the Nexus sidecar, for a program that embeds Nexus. The sidecar is always a separate process
  3 │  * (`sidecar.ts`): it takes the client lease, recovers a pending restore, loads managed policy and applies the approval
  4 │  * mode and verification itself, so an embedder gets exactly the gates the TUI gets and cannot start without them.
  5 │  *
  6 │  * This module's runtime imports are node builtins and the bounded line reader only, and importing it does nothing: it
  7 │  * reads no environment, HOME or argv, writes nothing and starts no timer (cli/test/lib_entry.test.ts).
  8 │  *
  9 │  * Approvals: the embedder answers each request "approve" or anything else (a denial). The client cannot approve
 10 │  * "always": no method sends `always: true`, and there is no raw send.
 11 │  */
 12 │ import { spawn } from "node:child_process";
 13 │ import { EventEmitter } from "node:events";
 14 │ import { fileURLToPath } from "node:url";
 15 │ import type { Readable, Writable } from "node:stream";
 16 │ import { BoundedLineReader } from "./acp/jsonrpc.js";
 17 │ import { ACP_MAX_CHILD_LINE_BYTES } from "./acp/types.js";
 18 │ import type { ErrorCode, SidecarCommand, SidecarEvent } from "./protocol.js";
 19 │ 
 20 │ /** The sidecar protocol version this client writes; equal to `PROTOCOL_VERSION` in protocol.ts (a test compares them). */
 21 │ export const CLIENT_PROTOCOL_VERSION = 1;
 22 │ const STDERR_TAIL_BYTES = 64 * 1024;
 23 │ const KILL_AFTER_TERM_MS = 5_000;
 24 │ 
 25 │ type EventOf<T extends SidecarEvent["type"]> = Extract<SidecarEvent, { type: T }>;
 26 │ export type ApprovalRequest = EventOf<"approval.request">;
 27 │ /** "approve" lets this one call run. Every other answer denies it, as does a handler that throws. */
 28 │ export type ApprovalDecision = "approve" | "deny";
 29 │ export type ApprovalHandler = (request: ApprovalRequest) => ApprovalDecision | Promise<ApprovalDecision>;
 30 │ 
 31 │ export interface PromptOptions {
 32 │   /** Called for every approval the turn asks for. Without it every approval is denied. */
 33 │   onApproval?: ApprovalHandler;
 34 │   /** Aborting cancels the turn; the promise still resolves with the turn's (interrupted) result. */
 35 │   signal?: AbortSignal;
 36 │ }
 37 │ 
 38 │ export interface SpawnSidecarOptions {
 39 │   workspace: string;
 40 │   endpoint?: string;
 41 │   model?: string;
 42 │   /** The sidecar's default is "review". "auto" is not offered here. */
 43 │   mode?: "review" | "read-only";
 44 │   authoritativeVerifier?: string;
 45 │   deliverableFiles?: readonly string[];
 46 │   sandbox?: string;
 47 │   /** Further sidecar options, appended as given. These are the embedder's own authority (it could pass `-y`). */
 48 │   extraArgs?: readonly string[];
 49 │   /** The child's environment (default: this process's). The child reads its settings from it; this module does not. */
 50 │   env?: NodeJS.ProcessEnv;
 51 │   /** The Node binary to run the sidecar with (default: the one running this process). */
 52 │   node?: string;
 53 │   /** The sidecar script (default: the one next to this module). */
 54 │   sidecarScript?: string;
 55 │   /** Aborting stops the child (SIGTERM), during start-up or later. */
 56 │   signal?: AbortSignal;
 57 │   /** How long to wait for the sidecar's `hello` (default 30 s). */
 58 │   readyTimeoutMs?: number;
 59 │ }
 60 │ 
 61 │ export type SidecarClientErrorCode = ErrorCode | "ABORTED" | "CHILD_EXITED" | "CLOSED" | "SPAWN_FAILED" | "TIMEOUT";
 62 │ 
 63 │ export class SidecarClientError extends Error {
 64 │   constructor(public readonly code: SidecarClientErrorCode, message: string) {
 65 │     super(message);
 66 │     this.name = "SidecarClientError";
 67 │   }
 68 │ }
 69 │ 
 70 │ export interface SidecarExit {
 71 │   code: number | null;
 72 │   signal: NodeJS.Signals | null;
 73 │ }
 74 │ 
 75 │ /** The part of a child process the client uses. */
 76 │ export interface SidecarChild {
 77 │   readonly pid?: number;
 78 │   readonly stdin: Writable | null;
 79 │   readonly stdout: Readable | null;
 80 │   readonly stderr: Readable | null;
 81 │   /** Signals this one process (never a process group). */
 82 │   kill(signal?: NodeJS.Signals): boolean;
 83 │   once(event: "exit", listener: (code: number | null, signal: NodeJS.Signals | null) => void): unknown;
 84 │   once(event: "error", listener: (error: Error) => void): unknown;
 85 │ }
 86 │ 
 87 │ /** What the client may write. No member carries allow-always: an approval is always for one call. */
 88 │ type ClientCommand = Exclude<SidecarCommand, { type: "approve" }> | { type: "approve"; id: string; always: false };
 89 │ 
 90 │ interface Pending {
 91 │   /** The event type that answers the request. */
 92 │   answer: SidecarEvent["type"];
 93 │   resolve(event: any): void;
 94 │   reject(error: Error): void;
 95 │ }
 96 │ 
 97 │ interface ClientEvents {
 98 │   /** Every well-formed event the sidecar writes, `hello` included. */
 99 │   event: [event: SidecarEvent];
100 │   /** A line that was not a protocol event (not JSON, not an object with a `type`, another version, or over 16 MiB). It is dropped. */
101 │   "protocol-error": [message: string];
102 │   exit: [exit: SidecarExit];
103 │ }
104 │ 
105 │ export class SidecarClient {
106 │   private readonly emitter = new EventEmitter<ClientEvents>();
107 │   private readonly pending = new Map<string, Pending>();
108 │   private readonly stderrChunks: Buffer[] = [];
109 │   private stderrBytes = 0;
110 │   private seq = 0;
111 │   private activePrompt?: { id: string; onApproval?: ApprovalHandler };
112 │   private helloEvent?: EventOf<"hello">;
113 │   private exited?: SidecarExit;
114 │   private inputFailure?: SidecarClientError;
115 │   private outputFailure?: SidecarClientError;
116 │   private shutdownPromise?: Promise<SidecarExit>;
117 │ 
118 │   /** `spawnSidecar` constructs the client; a caller normally does not. */
119 │   constructor(private readonly child: SidecarChild) {
120 │     const reader = new BoundedLineReader(ACP_MAX_CHILD_LINE_BYTES);
121 │     const take = (events: ReturnType<BoundedLineReader["push"]>): void => {
122 │       for (const event of events) {
123 │         if (event.kind === "oversized") this.emitter.emit("protocol-error", `a line longer than ${ACP_MAX_CHILD_LINE_BYTES} bytes was discarded`);
124 │         else this.takeLine(event.text);
125 │       }
126 │     };
127 │     child.stdout?.on("data", (chunk: Buffer) => take(reader.push(chunk)));
128 │     child.stdout?.on("end", () => {
129 │       take(reader.end());
130 │       this.failOutput();
131 │     });
132 │     child.stdout?.on("error", (error: Error) => this.failOutput(error));
133 │     child.stderr?.on("data", (chunk: Buffer) => this.keepStderr(chunk));
134 │     // A write after the child closed its end (EPIPE) rejects pending requests instead of hanging them or
135 │     // becoming an uncaught error in the embedder.
136 │     child.stdin?.on("error", (error: Error) => this.failInput(error));
137 │     child.once("exit", (code, signal) => this.onExit({ code, signal }));
138 │     child.once("error", () => this.onExit({ code: null, signal: null }));
139 │   }
140 │ 
141 │   /** The sidecar's `hello`; set before `spawnSidecar` resolves. */
142 │   get hello(): EventOf<"hello"> | undefined {
143 │     return this.helloEvent;
144 │   }
145 │ 
146 │   get pid(): number | undefined {
147 │     return this.child.pid;
148 │   }
149 │ 
150 │   /** The last 64 KiB the sidecar wrote to stderr, for the embedder's own diagnostics. The client never prints it. */
151 │   get stderrTail(): string {
152 │     return Buffer.concat(this.stderrChunks).toString("utf8");
153 │   }
154 │ 
155 │   on<K extends keyof ClientEvents>(name: K, listener: (...args: ClientEvents[K]) => void): this {
156 │     (this.emitter as EventEmitter).on(name, listener as (...args: unknown[]) => void);
157 │     return this;
158 │   }
159 │ 
160 │   off<K extends keyof ClientEvents>(name: K, listener: (...args: ClientEvents[K]) => void): this {
161 │     (this.emitter as EventEmitter).off(name, listener as (...args: unknown[]) => void);
162 │     return this;
163 │   }
164 │ 
165 │   /** Optional version negotiation; a client that skips it gets protocol 1. */
166 │   initialize(client: { name: string; version: string }): Promise<EventOf<"initialized">> {
167 │     const id = this.nextId();
168 │     return this.request({ type: "initialize", id, client }, id, "initialized");
169 │   }
170 │ 
171 │   /**
172 │    * Runs one turn and resolves with its `turn.result` event (whatever the outcome: read `turn.outcome`). One turn at a
173 │    * time: a second call while one runs rejects with code BUSY. Rejects when the sidecar answers the prompt with an error
174 │    * or exits first.
175 │    */
176 │   async prompt(text: string, options: PromptOptions = {}): Promise<EventOf<"turn.result">> {
177 │     if (this.activePrompt) throw new SidecarClientError("BUSY", "a prompt is already running on this client");
178 │     if (options.signal?.aborted) throw new SidecarClientError("ABORTED", "the prompt was aborted before it was sent");
179 │     const id = this.nextId();
180 │     this.activePrompt = { id, onApproval: options.onApproval };
181 │     const onAbort = (): void => this.cancel();
182 │     options.signal?.addEventListener("abort", onAbort, { once: true });
183 │     try {
184 │       return await this.request({ type: "prompt.submit", id, text }, id, "turn.result");
185 │     } finally {
186 │       options.signal?.removeEventListener("abort", onAbort);
187 │       this.activePrompt = undefined;
188 │     }
189 │   }
190 │ 
191 │   /** The evidence receipt of the last turn. */
192 │   receipt(): Promise<EventOf<"receipt">> {
193 │     const id = this.nextId();
194 │     return this.request({ type: "receipt", id }, id, "receipt");
195 │   }
196 │ 
197 │   /** Cancels the running turn, if any; its `prompt` promise then resolves with the interrupted result. */
198 │   cancel(): void {
199 │     this.write({ type: "cancel" });
200 │   }
201 │ 
202 │   /**
203 │    * Stops the sidecar: asks it to shut down and closes its stdin; if it has not exited after `graceMs`, SIGTERM, and
204 │    * SIGKILL 5 s later. Only the child itself is signalled. Resolves with how it exited; safe to call more than once.
205 │    */
206 │   shutdown(options: { graceMs?: number } = {}): Promise<SidecarExit> {
207 │     this.shutdownPromise ??= new Promise<SidecarExit>((resolve) => {
208 │       if (this.exited) return resolve(this.exited);
209 │       let timer: NodeJS.Timeout = setTimeout(() => {
210 │         this.child.kill("SIGTERM");
211 │         timer = setTimeout(() => this.child.kill("SIGKILL"), KILL_AFTER_TERM_MS);
212 │       }, options.graceMs ?? 10_000);
213 │       this.emitter.once("exit", (exit) => {
214 │         clearTimeout(timer);
215 │         resolve(exit);
216 │       });
217 │       this.write({ type: "shutdown" });
218 │       this.child.stdin?.end();
219 │     });
220 │     return this.shutdownPromise;
221 │   }
222 │ 
223 │   private nextId(): string {
224 │     return `lib-${++this.seq}`;
225 │   }
226 │ 
227 │   private request<T extends SidecarEvent["type"]>(command: ClientCommand, id: string, answer: T): Promise<EventOf<T>> {
228 │     return new Promise<EventOf<T>>((resolve, reject) => {
229 │       if (this.inputFailure) return reject(this.inputFailure);
230 │       if (this.outputFailure) return reject(this.outputFailure);
231 │       if (this.exited || this.shutdownPromise) return reject(new SidecarClientError("CLOSED", "the sidecar has exited or is shutting down"));
232 │       if (!this.child.stdin?.writable) return reject(new SidecarClientError("CLOSED", "the sidecar input is closed"));
233 │       this.pending.set(id, { answer, resolve, reject });
234 │       const failure = this.write(command);
235 │       if (failure) {
236 │         this.pending.delete(id);
237 │         reject(failure);
238 │       }
239 │     });
240 │   }
241 │ 
242 │   /** The only writer. A false result is a closed or failed input stream, not ordinary writable backpressure. */
243 │   private write(command: ClientCommand): SidecarClientError | undefined {
244 │     if (this.inputFailure) return this.inputFailure;
245 │     if (this.outputFailure) return this.outputFailure;
246 │     const stdin = this.child.stdin;
247 │     if (this.exited || !stdin || !stdin.writable) return new SidecarClientError("CLOSED", "the sidecar input is closed");
248 │     try {
249 │       stdin.write(`${JSON.stringify({ v: CLIENT_PROTOCOL_VERSION, ...command })}\n`);
250 │       return undefined;
251 │     } catch (error) {
252 │       return this.failInput(error instanceof Error ? error : new Error(String(error)));
253 │     }
254 │   }
255 │ 
256 │   private failInput(error: Error): SidecarClientError {
257 │     this.inputFailure ??= new SidecarClientError("CLOSED", `the sidecar input failed: ${error.message}`);
258 │     for (const waiting of this.pending.values()) waiting.reject(this.inputFailure);
259 │     this.pending.clear();
260 │     return this.inputFailure;
261 │   }
262 │ 
263 │   private failOutput(error?: Error): SidecarClientError {
264 │     this.outputFailure ??= new SidecarClientError("CHILD_EXITED", error
265 │       ? `the sidecar output failed: ${error.message}`
266 │       : "the sidecar closed its output before answering");
267 │     for (const waiting of this.pending.values()) waiting.reject(this.outputFailure);
268 │     this.pending.clear();
269 │     return this.outputFailure;
270 │   }
271 │ 
272 │   private takeLine(line: string): void {
273 │     let raw: unknown;
274 │     try {
275 │       raw = JSON.parse(line);
276 │     } catch {
277 │       this.emitter.emit("protocol-error", "a line was not valid JSON");
278 │       return;
279 │     }
280 │     if (!raw || typeof raw !== "object" || Array.isArray(raw) || typeof (raw as { type?: unknown }).type !== "string") {
281 │       this.emitter.emit("protocol-error", "a line was not a protocol event");
282 │       return;
283 │     }
284 │     if ((raw as { v?: unknown }).v !== CLIENT_PROTOCOL_VERSION) {
285 │       this.emitter.emit("protocol-error", `an event of protocol version ${String((raw as { v?: unknown }).v)} was dropped`);
286 │       return;
287 │     }
288 │     const event = raw as SidecarEvent;
289 │     if (event.type === "hello") this.helloEvent ??= event;
290 │     else if (event.type === "approval.request") void this.answerApproval(event);
291 │     // No choice is granted on the embedder's behalf (the others drop the rollback checkpoint or persist sensitive
292 │     // content): the turn is cancelled, which the sidecar takes as the choice "cancel", instead of waiting for ever.
293 │     else if (event.type === "checkpoint.choice.request") this.cancel();
294 │     else this.settle(event);
295 │     this.emitter.emit("event", event);
296 │   }
297 │ 
298 │   private settle(event: SidecarEvent): void {
299 │     const id = event.type === "turn.result" ? event.turn_id : "id" in event ? event.id : undefined;
300 │     const waiting = typeof id === "string" ? this.pending.get(id) : undefined;
301 │     if (!waiting || typeof id !== "string") return;
302 │     if (event.type === "error") {
303 │       this.pending.delete(id);
304 │       waiting.reject(new SidecarClientError(event.code, String(event.message)));
305 │     } else if (event.type === waiting.answer) {
306 │       this.pending.delete(id);
307 │       waiting.resolve(event);
308 │     }
309 │   }
310 │ 
311 │   /** Approve once only on the handler's exact "approve"; no handler, any other value or a throw is a denial. */
312 │   private async answerApproval(request: ApprovalRequest): Promise<void> {
313 │     let decision: unknown = "deny";
314 │     try {
315 │       decision = await this.activePrompt?.onApproval?.(request);
316 │     } catch {
317 │       decision = "deny";
318 │     }
319 │     if (decision === "approve") this.write({ type: "approve", id: request.id, always: false });
320 │     else this.write({ type: "deny", id: request.id });
321 │   }
322 │ 
323 │   private keepStderr(chunk: Buffer): void {
324 │     this.stderrChunks.push(chunk);
325 │     this.stderrBytes += chunk.length;
326 │     while (this.stderrChunks.length > 1 && this.stderrBytes - this.stderrChunks[0].length >= STDERR_TAIL_BYTES) {
327 │       this.stderrBytes -= (this.stderrChunks.shift() as Buffer).length;
328 │     }
329 │     if (this.stderrBytes > STDERR_TAIL_BYTES) {
330 │       this.stderrChunks[0] = this.stderrChunks[0].subarray(this.stderrBytes - STDERR_TAIL_BYTES);
331 │       this.stderrBytes = STDERR_TAIL_BYTES;
332 │     }
333 │   }
334 │ 
335 │   private onExit(exit: SidecarExit): void {
336 │     if (this.exited) return;
337 │     this.exited = exit;
338 │     const error = new SidecarClientError("CHILD_EXITED", `the sidecar exited (${exit.signal ?? `code ${exit.code}`}) before it answered`);
339 │     for (const waiting of this.pending.values()) waiting.reject(error);
340 │     this.pending.clear();
341 │     this.emitter.emit("exit", exit);
342 │   }
343 │ }
344 │ 
345 │ function sidecarCommand(options: SpawnSidecarOptions): { node: string; args: string[] } {
346 │   // Run from source (tests, a checkout under tsx) the sidecar is the .ts file next to this one and needs the same loader.
347 │   const fromSource = import.meta.url.endsWith(".ts");
348 │   const script = options.sidecarScript ?? fileURLToPath(new URL(fromSource ? "./sidecar.ts" : "./sidecar.js", import.meta.url));
349 │   const args = script.endsWith(".ts") ? ["--import", import.meta.resolve("tsx"), script] : [script];
350 │   args.push("-w", options.workspace);
351 │   if (options.endpoint) args.push("-e", options.endpoint);
352 │   if (options.model) args.push("-m", options.model);
353 │   if (options.mode) args.push("--mode", options.mode);
354 │   if (options.authoritativeVerifier) args.push("--authoritative-verifier", options.authoritativeVerifier);
355 │   for (const file of options.deliverableFiles ?? []) args.push("--deliverable-file", file);
356 │   if (options.sandbox) args.push("--sandbox", options.sandbox);
357 │   args.push(...(options.extraArgs ?? []));
358 │   return { node: options.node ?? process.execPath, args };
359 │ }
360 │ 
361 │ /**
362 │  * Starts a sidecar for `workspace` and resolves once it has said `hello`. The child is this process's own child with
363 │  * piped stdio; stop it with `client.shutdown()`. Every failure, an invalid option included, is a rejection.
364 │  */
365 │ export async function spawnSidecar(options: SpawnSidecarOptions): Promise<SidecarClient> {
366 │   const { node, args } = sidecarCommand(options);
367 │   const child = spawn(node, args, { stdio: ["pipe", "pipe", "pipe"], env: options.env, signal: options.signal });
368 │   const client = new SidecarClient(child);
369 │   return new Promise<SidecarClient>((resolve, reject) => {
370 │     const onEvent = (event: SidecarEvent): void => {
371 │       if (event.type === "hello") done();
372 │     };
373 │     const onExit = (exit: SidecarExit): void => {
374 │       done(new SidecarClientError(child.pid === undefined ? "SPAWN_FAILED" : "CHILD_EXITED", `the sidecar did not start (${exit.signal ?? `code ${exit.code}`}); see the error's stderrTail`));
375 │     };
376 │     const timer = setTimeout(() => {
377 │       child.kill("SIGKILL");
378 │       done(new SidecarClientError("TIMEOUT", "the sidecar did not say hello in time"));
379 │     }, options.readyTimeoutMs ?? 30_000);
380 │     const done = (error?: SidecarClientError): void => {
381 │       clearTimeout(timer);
382 │       client.off("event", onEvent).off("exit", onExit);
383 │       if (error) reject(Object.assign(error, { stderrTail: client.stderrTail }));
384 │       else resolve(client);
385 │     };
386 │     client.on("event", onEvent).on("exit", onExit);
387 │   });
388 │ }
