  { kind: "tools", calls: [{ name: "run_command", args: { command: "printf 'exports.add = (a, b) => a + b;\\n' > add.js" } }] },
  { kind: "tools", calls: [{ name: "run_command", args: { command: "node --test" } }] },
  { kind: "tools", calls: [{ name: "task_completed", args: { summary: "Fixed add()" } }] },
